const item = $input.first();
const binaryKeys = Object.keys(item.binary || {});

if (!binaryKeys.length) {
  throw new Error('No image file found in the form submission');
}

const binaryKey = binaryKeys[0];
const file = item.binary[binaryKey];

const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const base64Image = buffer.toString('base64');

const purchasePrice = parseFloat(
  item.json['Purchase Price'] ||
  item.json['purchase_price'] ||
  item.json.purchasePrice ||
  0
);
const source = item.json['Source'] || item.json.source || 'Unknown';

const geminiBody = {
  contents: [{
    parts: [
      {
        inline_data: {
          mime_type: file.mimeType || 'image/jpeg',
          data: base64Image
        }
      },
      {
        text: 'Analyze this item and respond ONLY with a valid JSON object — no markdown, no code fences, no extra text. Include these exact keys: itemName (string), brand (string), model (string or null), category (one of: Electronics|Clothing|Toys|Books|Tools|Home|Sports|Other), condition (one of: New|Like New|Very Good|Good|Acceptable|Unknown), estimatedRetailPrice (number in USD, 0 if unknown), searchKeywords (string of 3–5 words that work best as an eBay search query), confidence (one of: high|medium|low).'
      }
    ]
  }]
};

return [{
  json: {
    geminiBody,
    purchasePrice,
    source
  }
}];

const geminiResponse = $input.first().json;
const prev = $('Prepare Image').first().json;

const rawText = geminiResponse?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';

let itemInfo;
try {
  const cleaned = rawText
    .replace(/```json\s*/gi, '')
    .replace(/```\s*/g, '')
    .trim();
  itemInfo = JSON.parse(cleaned);
} catch (_) {
  itemInfo = {
    itemName: 'Unknown Item',
    brand: 'Unknown',
    model: null,
    category: 'Other',
    condition: 'Unknown',
    estimatedRetailPrice: 0,
    searchKeywords: 'used item',
    confidence: 'low'
  };
}

const searchQuery = (itemInfo.searchKeywords || `${itemInfo.brand} ${itemInfo.model || itemInfo.itemName}`)
  .replace(/[^a-zA-Z0-9 ]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .substring(0, 100);

const encodedKeywords = encodeURIComponent(searchQuery);
const base = 'https://svcs.ebay.com/services/search/FindingService/v1';
const common = `SERVICE-VERSION=1.0.0&RESPONSE-DATA-FORMAT=JSON&paginationInput.entriesPerPage=50`;

const soldUrl = `${base}?OPERATION-NAME=findCompletedItems&${common}&keywords=${encodedKeywords}&itemFilter(0).name=SoldItemsOnly&itemFilter(0).value=true&sortOrder=EndTimeSoonest`;
const activeUrl = `${base}?OPERATION-NAME=findItemsByKeywords&${common}&keywords=${encodedKeywords}&sortOrder=PricePlusShippingLowest`;

return [{
  json: {
    itemInfo,
    searchQuery,
    purchasePrice: prev.purchasePrice,
    source: prev.source,
    soldUrl,
    activeUrl
  }
}];

const activeResults = $input.first().json;
const soldResults = $('eBay Sold').first().json;
const itemData = $('Parse Item').first().json;

const { purchasePrice, source, itemInfo, searchQuery } = itemData;

const soldItems = soldResults?.findCompletedItemsResponse?.[0]?.searchResult?.[0]?.item || [];
const soldPrices = soldItems
  .map(i => parseFloat(i?.sellingStatus?.[0]?.currentPrice?.[0]?.__value__ || 0))
  .filter(p => p > 0);

const activeItems = activeResults?.findItemsByKeywordsResponse?.[0]?.searchResult?.[0]?.item || [];
const activePrices = activeItems
  .map(i => parseFloat(i?.sellingStatus?.[0]?.currentPrice?.[0]?.__value__ || 0))
  .filter(p => p > 0);

const avg = arr => arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : 0;

const avgSoldPrice = avg(soldPrices);
const avgActivePrice = avg(activePrices);
const lowestActive = activePrices.length ? Math.min(...activePrices) : 0;

const EBAY_FEE = 0.1325;
const SHIPPING_EST = 8.00;
const ebayFees = avgSoldPrice * EBAY_FEE;
const netProfit = avgSoldPrice - purchasePrice - ebayFees - SHIPPING_EST;
const profitMargin = purchasePrice > 0 ? (netProfit / purchasePrice) * 100 : 0;

const stalePriceGap = avgSoldPrice > 0 ? (avgActivePrice - avgSoldPrice) / avgSoldPrice : 0;
const hasStaleListings = stalePriceGap > 0.25;
const fastSalePrice = avgSoldPrice > 0 ? avgSoldPrice * 0.88 : 0;
const optimalPrice = avgSoldPrice > 0 ? avgSoldPrice * 0.97 : 0;
const premiumPrice = avgSoldPrice > 0 ? avgSoldPrice * 1.05 : 0;
const staleThreshold = avgSoldPrice > 0 ? avgSoldPrice * 1.20 : 0;

let recommendation, badgeColor;
if (soldPrices.length < 3) {
  recommendation = 'LOW DATA';
  badgeColor = '#6c757d';
} else if (profitMargin > 50) {
  recommendation = 'BUY';
  badgeColor = '#28a745';
} else if (profitMargin >= 20) {
  recommendation = 'MAYBE';
  badgeColor = '#ffc107';
} else {
  recommendation = 'PASS';
  badgeColor = '#dc3545';
}

return [{
  json: {
    itemInfo, purchasePrice, source, searchQuery,
    soldStats: {
      count: soldPrices.length,
      avg: avgSoldPrice.toFixed(2),
      min: soldPrices.length ? Math.min(...soldPrices).toFixed(2) : '0.00',
      max: soldPrices.length ? Math.max(...soldPrices).toFixed(2) : '0.00'
    },
    activeStats: {
      count: activePrices.length,
      avg: avgActivePrice.toFixed(2),
      lowest: lowestActive.toFixed(2)
    },
    profitCalc: {
      avgSoldPrice: avgSoldPrice.toFixed(2),
      ebayFees: ebayFees.toFixed(2),
      shippingEst: SHIPPING_EST.toFixed(2),
      netProfit: netProfit.toFixed(2),
      profitMargin: profitMargin.toFixed(1)
    },
    pricingTiers: {
      fastSale: fastSalePrice.toFixed(2),
      optimal: optimalPrice.toFixed(2),
      premium: premiumPrice.toFixed(2),
      staleThreshold: staleThreshold.toFixed(2)
    },
    stalePriceGap: (stalePriceGap * 100).toFixed(1),
    hasStaleListings,
    recommendation, badgeColor
  }
}];

